ALTER TABLE "knowledge_graph_relations" ADD COLUMN "assertion" jsonb DEFAULT '{"tense":"unspecified","polarity":"positive","modality":"unverified"}'::jsonb NOT NULL;--> statement-breakpoint
ALTER TABLE "knowledge_graph_relations" ADD CONSTRAINT "knowledge_graph_relations_assertion_check" CHECK ("knowledge_graph_relations"."assertion"->>'tense' IN ('present','past','future','unspecified') AND "knowledge_graph_relations"."assertion"->>'polarity' IN ('positive','negative') AND "knowledge_graph_relations"."assertion"->>'modality' IN ('asserted','possible','conditional','reported','hypothetical','unverified'));